async function deleteShotVideoRecords(target,button){if(!confirm('删除本镜已生成的视频记录？删除后一键生成会重新处理本镜。'))return;if(button)button.disabled=true;try{if(typeof flushDisk==='function')await flushDisk();if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先读取最新项目后再删除');const projectId=data.project_id,result=await frontFetch('/api/video/delete-shot',{project_id:projectId,target_id:target.shot_id||target.clip_id,confirm:true});if(data.project_id!==projectId)return;Object.assign(data,result.project);if(typeof diskRevision!=='undefined')diskRevision=result.revision;if(typeof lastDiskData!=='undefined')lastDiskData=JSON.stringify(data);if(typeof browserSave==='function')browserSave();videoBatchPreview=null;render();toast('本镜视频记录已删除，可重新生成');}catch(e){toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}}
(()=>{const previous=stage;stage=function(){previous();if(tab!==4)return;document.querySelectorAll('[data-main-video],[data-open-video-clip]').forEach(open=>{const main=open.hasAttribute('data-main-video'),index=Number(main?open.dataset.mainVideo:open.dataset.openVideoClip),target=main?data.shots?.[index]:data.shotScript?.generation_clips?.[index];if(!target||!selectedShotVideo(target))return;const card=open.closest('.card');if(card?.querySelector('[data-delete-shot-video]'))return;const button=document.createElement('button');button.type='button';button.dataset.deleteShotVideo=target.shot_id||target.clip_id;button.textContent='删除本镜视频';button.style.cssText='margin-left:8px;color:#e8bcb9';button.disabled=videoBusy(target.videoJob);button.onclick=()=>deleteShotVideoRecords(target,button);open.after(button);});};render();})();